package net.civeira.phylax.feature.identity.tenanttermsofuse.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenanttermsofuse.domain.TenantTermsOfUse;
import net.civeira.phylax.feature.identity.tenanttermsofuse.domain.valueobject.DocumentVO;

@RequiredArgsConstructor
public class DocumentValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<DocumentVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @param document
   * @return
   */
  public T document(DocumentVO document) {
    this.value = Optional.of(document);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param document
   * @return
   */
  public T document(Optional<DocumentVO> document) {
    this.value = document;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param document
   * @return
   */
  public T document(String document) {
    this.value = Optional.of(DocumentVO.from(document));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T documentNull() {
    this.value = Optional.of(DocumentVO.nullValue());
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getDocument() {
    return value.flatMap(DocumentVO::getDocument);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<DocumentVO> getDocumentValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public DocumentVO readDocument(final Optional<TenantTermsOfUse> original,
      final ConstraintFailList fails) {
    return value
        .orElse(original.map(TenantTermsOfUse::getDocumentValue).orElseGet(DocumentVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetDocument() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetDocumentIfMatches(final String field) {
    if ("document".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
